/// O ajuste entre `a` e `b` (a letra acentuada usa o par da letra-base), em milésimos de em; o
/// código (monoespaçado) não tem.
pub fn par(a: char, b: char, estilo: u8) -> i16 {
    if estilo & CODIGO != 0 {
        return 0;
    }
    let tabela: &[(char, char, i16)] = if estilo & SERIFA != 0 {
        match (estilo & NEGRITO != 0, estilo & ITALICO != 0) {
            (false, false) => &SERIFA_REGULAR_KERN,
            (true, false) => &SERIFA_NEGRITO_KERN,
            (false, true) => &SERIFA_ITALICO_KERN,
            (true, true) => &SERIFA_NEGRITO_ITALICO_KERN,
        }
    } else if estilo & NEGRITO != 0 {
        &SANS_NEGRITO
    } else {
        &SANS_REGULAR
    };
    let (a, b) = (crate::medida::base_do_acento(a), crate::medida::base_do_acento(b));
    tabela.binary_search_by(|&(x, y, _)| (x, y).cmp(&(a, b))).map_or(0, |i| tabela[i].2)
}
